questionvariables.text:
a  : rand(5)+1;
b  : rand(5)+1;
c  : rand(5)+1;
d  : rand(5)+1;
ff : rand(5)+1;
g  : rand(5)+1;
h  : rand(5)+1;
scenario : rand(3);                        /* 0 = even, 1 = odd, 2 = neither */
e1 : if scenario=0 then 1 elseif scenario=1 then 0 else 1;
e2 : if scenario=0 then 0 elseif scenario=1 then 1 else 1;
numer : e1*(a*x^4+b*x^2+c) + e2*(d*x^3+ff*x);
denom : g*x^2+h;
expr : numer/denom;
fnegx : ratsimp(subst(x=-x,expr));
is_even : is(ratsimp(fnegx-expr)=0);
is_odd  : is(ratsimp(fnegx+expr)=0);
even_opt : "even"; odd_opt : "odd"; neither_opt : "neither";
classatom  : if is_even then even_opt elseif is_odd then odd_opt else neither_opt;
classlabel : if is_even then "even" elseif is_odd then "odd" else "neither";
classopts  : [[even_opt, is_even, "Even"],[odd_opt, is_odd, "Odd"],[neither_opt, not(is_even) and not(is_odd), "Neither"]];
/* Diagnostics for part (a), chosen per scenario so that each is a genuine error that never equals k(-x)
   (checked in Maxima over random parameter draws for all three scenarios):
   diagA: even k: flipped the sign of every term (-k(x)); odd or neither k: did not substitute at all (k(x)).
   diagB: odd k: changed the sign of the cubic term only, forgot the x term;
          even or neither k: correct k(-x) but with the sign of the constant term also flipped. */
diagA : if scenario=0 then -expr else expr;
diagB : if scenario=1 then (-d*x^3+ff*x)/denom else (e1*(a*x^4+b*x^2-c)-e2*(d*x^3+ff*x))/denom;
